int qid = msgget(key, IPC_CREAT | 0666);

struct { long mtype; char text[100]; } msg;
msg.mtype = 1;
strcpy(msg.text, "hello");
msgsnd(qid, &msg, sizeof(msg.text), 0);      // send a type 1 message

struct { long mtype; char text[100]; } received;
msgrcv(qid, &received, sizeof(received.text), 1, 0); // receive only type 1

msgctl(qid, IPC_RMID, NULL);                  // explicitly remove the queue

